() => {
  // 找到包含固化卡片标题的元素并滚动到它
  const els = [...document.querySelectorAll('h3, div, span')];
  const target = els.find(e => e.textContent && e.textContent.trim() === '客户总数_P214验证（按industry切分）');
  if (target) {
    target.scrollIntoView({ block: 'start', behavior: 'instant' });
    return { found: true, rect: target.getBoundingClientRect() };
  }
  // 否则滚动所有可滚动容器到底部
  const scrollables = [...document.querySelectorAll('*')].filter(e => e.scrollHeight > e.clientHeight + 50);
  const info = scrollables.map(e => ({ tag: e.tagName, cls: (e.className||'').toString().slice(0,40), sh: e.scrollHeight, ch: e.clientHeight }));
  scrollables.forEach(e => e.scrollTop = e.scrollHeight);
  return { found: false, scrollables: info };
}

